def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        bid = DAILY_SALARY * 0.35
        if hp <= 2 or no_water >= 1:
            bid = DAILY_SALARY * 0.75
        return float(min(budget, max(0.0, bid)))

    prev_bids = []
    urgent_count = 0
    rich_aggressive = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev:
            pbid = prev.get('bid')
            if pbid is not None:
                prev_bids.append(float(pbid))
                if pbid >= 95:
                    rich_aggressive += 1
            if opp.get('no_water_days', 0) >= 1:
                urgent_count += 1
            if prev.get('status') not in (None, 'ok'):
                urgent_count += 1
        else:
            if opp.get('no_water_days', 0) >= 1:
                urgent_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    likely_units = int(supply / WATER_REQ)
    contested = likely_units <= 1

    if hp <= 1:
        bid = max(105.0, highest_prev + 3.0)
    elif hp <= 2 or no_water >= 2:
        bid = max(92.0, highest_prev * 0.92 + 2.0)
    elif no_water >= 1:
        bid = max(78.0, avg_prev * 0.9 + 1.5)
    else:
        if contested:
            bid = max(66.0, min(88.0, avg_prev * 0.82 + 2.0))
            if urgent_count >= 2:
                bid += 8.0
            if rich_aggressive >= 2:
                bid -= 4.0
        else:
            bid = 34.0
            if highest_prev > 100:
                bid = 28.0
            elif highest_prev > 80:
                bid = 31.0
            if urgent_count >= 2:
                bid += 6.0

    if day >= 8:
        bid += 6.0
    if day >= 9 and hp <= 3:
        bid += 10.0

    if budget < DAILY_SALARY:
        bid = min(bid, budget * 0.9)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context['supply']
    day = day_context['day']

    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Extract yesterday bids from immediate previous_trace only
    prev_bids = []
    for oid, o in alive:
        pt = o.get('previous_trace', None) or {}
        b = pt.get('bid', None)
        if b is not None:
            prev_bids.append(float(b))

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_b = sorted(prev_bids, reverse=True)
        second_prev_bid = sorted_b[1]

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # Supply pressure: if supply is near max, water is plentiful => bid less
    # if supply is near min, bid more to secure required water.
    # supply is in [15,25]
    if supply <= MIN_SUPPLY:
        scarcity = 1.0
    elif supply >= MAX_SUPPLY:
        scarcity = 0.0
    else:
        scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)

    # Opponent aggressiveness heuristic from yesterday max bid
    # If someone bid very high yesterday, assume they will keep pressure.
    aggress = 0.0
    if highest_prev_bid > 0:
        aggress = min(1.0, highest_prev_bid / (DAILY_SALARY * 1.4))

    # Core bid targets
    # - Baseline depends on HP: lower HP => bid more to avoid death.
    # - Also slightly overbid relative to yesterday high to beat Cindy/Eric.
    if hp <= 2.0:
        base = DAILY_SALARY * (0.85 + 0.15 * scarcity)
    elif hp <= 4.0:
        base = DAILY_SALARY * (0.65 + 0.20 * scarcity)
    else:
        base = DAILY_SALARY * (0.52 + 0.18 * scarcity)

    # Competitive increment: try to be just above the likely top bidder if aggression is high.
    # Use second-highest as a softer alternative.
    if aggress >= 0.55:
        target = max(base, highest_prev_bid + 2.0)
    else:
        # If not very aggressive, still match around the top bid to ensure we get water.
        target = max(base, second_prev_bid + 1.5)

    # Budget safety cap: never bid more than we can afford.
    bid = min(budget, target)

    # If budget is extremely low, bid proportionally to avoid wasting.
    if budget <= DAILY_SALARY * 0.25:
        bid = min(budget, DAILY_SALARY * 0.18)

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10 # From meta-round state

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid minimal to save budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    # Determine if supply is tight
    num_potential_winners = int(day_context['supply'] / WATER_REQ)
    num_competitors = len(alive_opponents) + 1
    supply_is_tight = num_potential_winners < num_competitors

    bid_amount = DAILY_SALARY * 0.8 # Default base bid

    # Emergency HP - must win
    if my_status['hp'] <= 3: # Very critical HP
        bid_amount = DAILY_SALARY * 1.8 # Aggressive bid
        if highest_prev_bid > 0:
            bid_amount = max(bid_amount, highest_prev_bid + 15) # Outbid them significantly
    elif my_status['hp'] <= 5: # Critical HP
        bid_amount = DAILY_SALARY * 1.5
        if highest_prev_bid > 0:
            bid_amount = max(bid_amount, highest_prev_bid + 10)
    elif my_status['hp'] <= 7: # Moderate HP
        if supply_is_tight:
            bid_amount = DAILY_SALARY * 1.3
            if highest_prev_bid > 0:
                bid_amount = max(bid_amount, highest_prev_bid + 7)
        else:
            bid_amount = DAILY_SALARY * 1.1
            if highest_prev_bid > 0:
                bid_amount = max(bid_amount, highest_prev_bid + 3)
    else: # Good HP
        if supply_is_tight:
            bid_amount = DAILY_SALARY * 1.0
            if highest_prev_bid > 0:
                bid_amount = max(bid_amount, highest_prev_bid + 5) # Competitive
        else:
            bid_amount = DAILY_SALARY * 0.8
            if highest_prev_bid > 0:
                bid_amount = max(bid_amount, highest_prev_bid + 1) # Try to win cheaply

    # Ensure a minimum competitive bid against aggressive opponents, if HP allows
    min_competitive_bid = DAILY_SALARY * 0.7
    if bid_amount < min_competitive_bid and my_status['hp'] > 7: 
        bid_amount = min_competitive_bid

    # Ensure bid doesn't exceed budget
    final_bid = min(my_status['budget'], bid_amount)

    # Edge case: If budget is very low but need to survive, bid what's left.
    if my_status['hp'] <= 5 and my_status['budget'] > 0 and final_bid < DAILY_SALARY * 0.5:
        final_bid = my_status['budget'] * 0.95 # Bid almost everything if critical and budget is low.

    return final_bid
